static const struct { const char*n; uint32_t v; } cnames[]={{"red",0xFF0000},{"green",0x00C000},{"blue",0x5070FF},{"yellow",0xFFFF00},{"orange",0xFFA500},{"purple",0xC050C0},{"magenta",0xFF00FF},{"fuchsia",0xFF00FF},{"cyan",0x00FFFF},{"aqua",0x00FFFF},{"teal",0x00A0A0},{"lime",0x00FF00},{"pink",0xFFC0CB},{"gray",0xA0A0A0},{"grey",0xA0A0A0},{"white",0xFFFFFF},{"brown",0xC08040},{"gold",0xFFD700},{"navy",0x5070FF},{"maroon",0xC04040},{"violet",0xEE82EE},{0,0}};
static int hexv(int c){ c=lc(c); return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1; }
static uint8_t rgb256(uint32_t v){ int r=(v>>16)&255,g=(v>>8)&255,b=v&255; /* zu dunkle Schrift waere auf dem dunklen Grund unlesbar */ if((r*3+g*6+b)/10<90)return 0; int q=(r+g+b)/3; if(r/12==q/12&&g/12==q/12&&b/12==q/12){ int i=(q-8)/10; return (uint8_t)(232+(i<0?0:i>23?23:i)); } return (uint8_t)(16+36*((r+25)*5/255>5?5:(r+25)*5/255)+6*((g+25)*5/255>5?5:(g+25)*5/255)+((b+25)*5/255>5?5:(b+25)*5/255)); }
static uint8_t pcolor(const char*s,int n){ while(n&&ws(*s)){ s++; n--; } while(n&&(ws(s[n-1])||s[n-1]==';'))n--; if(n&&*s=='#'){ uint32_t v=0; if(n==4){ for(int i=1;i<4;i++){ int d=hexv(s[i]); if(d<0)return 0; v=v<<8|(uint32_t)(d*17); } return rgb256(v); } if(n==7){ for(int i=1;i<7;i++){ int d=hexv(s[i]); if(d<0)return 0; v=v<<4|(uint32_t)d; } return rgb256(v); } return 0; } if(n>4&&ieq(s,"rgb",3)){ uint32_t v=0; int k=0,i=3; while(i<n&&k<3){ while(i<n&&!(s[i]>='0'&&s[i]<='9'))i++; int x=0,dg=0; while(i<n&&s[i]>='0'&&s[i]<='9'&&dg<4){ x=x*10+s[i++]-'0'; dg++; } if(i<n&&s[i]=='%')return 0; if(x>255)x=255; v=v<<8|(uint32_t)x; k++; } return k==3?rgb256(v):0; } for(int i=0;cnames[i].n;i++) if((int)strlen(cnames[i].n)==n&&ieq(s,cnames[i].n,n))return rgb256(cnames[i].v); return 0; }
static uint8_t scolor(const char*s,int n){ for(int i=0;i+6<=n;i++) if(ieq(s+i,"color",5)&&(i==0||s[i-1]==';'||ws(s[i-1]))){ int j=i+5; while(j<n&&ws(s[j]))j++; if(j<n&&s[j]==':'){ j++; int k=j; while(k<n&&s[k]!=';'&&s[k]!='!')k++; return pcolor(s+j,k-j); } } return 0; }
/* ---------- Tabellen ---------- */
/* Misst eine einfache Tabelle vorab. 0: nicht ausrichten, sondern wie bisher mit Trennstrichen fliessen lassen */
static int tscan(const char*p,const char*e,int*cw,int*nc){ for(int i=0;i<TCOLS;i++)cw[i]=0; int col=0,span=1,in=0,len=0,sp=0,rows=0,maxc=0; const char*lim=e-p>262144?p+262144:e; int spansum=0; (void)spansum;
#define ENDCELL do{ if(in){ if(span==1&&col<TCOLS&&len>cw[col])cw[col]=len; col+=span; } in=0; }while(0)
  while(p<lim){ char ch=*p; if(ch=='<'){ if(p+3<lim&&p[1]=='!'&&p[2]=='-'&&p[3]=='-'){ p+=4; while(p+2<lim&&!(p[0]=='-'&&p[1]=='-'&&p[2]=='>'))p++; p+=3; continue; } const char*q=p+1; int cl=0; if(q<lim&&*q=='/'){ cl=1; q++; } char n[10]; int nl=0; while(q<lim&&alnum(*q)){ if(nl<9)n[nl++]=(char)lc(*q); q++; } n[nl]=0; const char*t=q; char qu=0; while(t<lim&&(*t!='>'||qu)){ if(qu){ if(*t==qu)qu=0; } else if(*t=='"'||*t=='\'')qu=*t; t++; } if(t>=lim)return 0;
#define N(s) (nl==sizeof(s)-1&&!strncmp(n,s,nl))
      if(N("table")){ if(!cl)return 0; ENDCELL; if(col>maxc)maxc=col; break; } if(N("tr")||N("thead")||N("tbody")||N("tfoot")){ ENDCELL; if(!cl&&N("tr")){ if(col>maxc)maxc=col; if(col)rows++; col=0; } } else if(N("caption")){ ENDCELL; in=0; } else if(N("td")||N("th")){ ENDCELL; if(!cl){ in=1; len=0; sp=0; span=1; for(const char*a=q;a+8<t;a++) if(ieq(a,"colspan",7)){ const char*b=a+7; while(b<t&&!(*b>='0'&&*b<='9'))b++; int v=0; while(b<t&&*b>='0'&&*b<='9'&&v<100)v=v*10+*b++-'0'; if(v>1)span=v; break; } if(col+span>TCOLS)return 0; } } else if(!cl&&(N("p")||N("div")||N("ul")||N("ol")||N("li")||N("br")||N("h1")||N("h2")||N("h3")||N("h4")||N("h5")||N("h6")||N("pre")||N("form")||N("input")||N("img")||N("button")||N("select")||N("textarea")||N("hr")||N("blockquote")))return 0; else if(!cl&&(N("script")||N("style"))){ t++; while(t+1<lim&&!(t[0]=='<'&&t[1]=='/'))t++; while(t<lim&&*t!='>')t++; } p=t+1; continue; }
    if(in){ if(ch=='&'){ const char*o; if(entity(p,lim,&o)){ if(sp&&len)len++; sp=0; len++; p=o; continue; } } if(ws(ch)){ sp=1; } else if(((uint8_t)ch&0xC0)!=0x80){ if(sp&&len)len++; sp=0; len++; } } p++; }
  if(col>maxc)maxc=col; if(col)rows++; *nc=maxc; return p<lim&&maxc>=2&&maxc<=TCOLS&&rows>=1; }
static void tcell(C*c,int span){ if(c->tcol>=c->tn)return; int t=c->tstop[c->tcol]; c->pend=0; if(c->tcol>0){ while(c->col<t-2&&c->col<c->w-1)put(c,' ',HS_NORM); if(c->col>=t-1&&c->col<c->w-1)put(c,' ',HS_NORM); uint16_t l=c->lk; c->lk=0; put(c,0xB3,HS_DIM); c->lk=l; put(c,' ',HS_NORM); } c->tcol+=span; }
